/* 粒子特效配置 */
.particles-1 {
  --count: 38;
  --color: #7C3AED;
  --size: 10px;
  --shape: circle;
  --speed: 3.0s;
  --spread: 116px;
  --opacity: 0.3;
  position: relative;
  overflow: hidden;
}

/* 粒子漂浮动画 */
@keyframes float-1 {
  0% { transform: translateY(var(--spread)) translateX(0); opacity: 0; }
  20% { opacity: var(--opacity); }
  100% { transform: translateY(calc(var(--spread) * -1)) translateX(-25px); opacity: 0; }
}

