      section:
        @class: "deep-dive"
        @data-deep-dive: "1"
        div:
          @class: card
          h2: 📚 深度解析：XML to YAML Converter
          h3:
            - 💡 常见使用场景
            - ❓ 常见问题（FAQ）
          ul:
            @class: "dd-list"
            li:
              - a: [object Object]
                #text: 配置转 YAML。
